  /// index 0-based (Ashwini=0).
  ///
  /// `GET /v1/chart/yogas`
  Future<T> yogas<T>({
    required BirthInput birth,
    Ayanamsa? ayanamsa,
    HouseSystem? houseSystem,
    bool? all,
    String? gender,
    RequestOptions? options,
  }) {
    final $q = <String, Object?>{}
      ..put('date', birth.date)
      ..put('time', birth.time)
      ..put('tz', birth.tz)
      ..put('lat', birth.lat)
      ..put('lon', birth.lon)
      ..put('ayanamsa', ayanamsa?.wire)
      ..put('house_system', houseSystem?.wire)
      ..put('all', all)
      ..put('gender', gender);
    return _c.request<T>('/v1/chart/yogas', $q, options);
  }
}
